from pathlib import Path
from html import escape
from hashlib import sha256
ROOT=Path(__file__).parent/'dist'
def t(es,en,tag='span',cls=''):
 return f'<{tag}'+(f' class="{cls}"' if cls else '')+f' data-es="{escape(es,quote=True)}" data-en="{escape(en,quote=True)}">{es}</{tag}>'
def a(es,en,href,cls='',extra=''): return f'<a href="{href}" class="{cls}" {extra}>{t(es,en)}</a>'
def btn(es,en,cls='',extra=''): return f'<button class="{cls}" {extra}>{t(es,en)}</button>'
def head(page='home'):
 versions={name:sha256((ROOT/name).read_bytes()).hexdigest()[:10] for name in ('navigation.css','navigation.js','app.js','directions.js')}
 style_version=sha256((ROOT/'styles.css').read_bytes()).hexdigest()[:10]
 extra_head='<link rel="stylesheet" href="/proforma.css"><script src="/vendor/three.min.js" defer></script><script src="/viewer-controls.js" defer></script><link rel="stylesheet" href="/spatial.css"><script src="/spatial-scene.js" defer></script><script src="/proforma.js" defer></script>' if page in ('proforma','project') else ''
 extra_head=extra_head.replace('/proforma.js', '/proforma.js?v='+sha256((ROOT/'proforma.js').read_bytes()).hexdigest()[:10])
 if page=='project': extra_head+='<link rel="stylesheet" href="/sector-map.css"><script src="/sector-scene.js" defer></script><script src="/sector-map.js" defer></script>'
 title={'home':'Alpha Builders · Concept Studio','project':'Pixel · Alpha Builders · Concept Studio','about':'Andean Software Lab · Nuestro equipo','proforma':'Inversión y equipo · Alpha Builders','proposal':'Propuesta digital · Alpha Builders'}.get(page,'Alpha Builders · Concept Studio')
 description='Andean Software Lab: desarrollo de software, producto e integraciones para la propuesta digital de Alpha Builders, por Martín Vélez Falconí y Alvaro Paz.' if page=='about' else 'Proforma demostrativa en tres niveles: bot de WhatsApp y gestor central, edificios en 2D, y modelos 3D con visitas virtuales.' if page=='proforma' else 'Propuesta conceptual para Alpha Builders: tres direcciones visuales y una experiencia de proyecto.'
 return f'''<!doctype html><html lang="es-EC"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{description}"><title>{title}</title><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' fill='%23212b22'/%3E%3Cpath d='M6 25L16 6l10 19h-5l-5-10-5 10Z' fill='%23d5bc7c'/%3E%3C/svg%3E"><link rel="stylesheet" href="/styles.css?v={style_version}"><link rel="stylesheet" href="/directions.css"><script>document.documentElement.classList.add('js')</script><script src="/navigation.js?v={versions['navigation.js']}" defer></script><script src="/app.js?v={versions['app.js']}" defer></script><script src="/directions.js?v={versions['directions.js']}" defer></script>{extra_head}<link rel="stylesheet" href="/navigation.css?v={versions['navigation.css']}"></head><body class="immersive page-{page}"><a class="skip" href="#main">{t('Saltar al contenido','Skip to content')}</a>
 {shell(page)}'''
def language():
 return f'<div class="lang-switch js-only" role="group" aria-label="Idioma / Language"><button data-lang="es" aria-pressed="true">ES</button><span>/</span><button data-lang="en" aria-pressed="false">EN</button></div>'
def shell(page):
 if page in ('home','project'):
  return f'<div class="preview-return">{a("← Volver a la propuesta","← Back to proposal","/propuesta/#opciones")}</div>'
 links=a('Resumen','Overview','/propuesta/#resumen')+a('Comparar opciones','Compare options','/propuesta/#opciones')+a('Inversión y equipo','Investment & team','/proforma/#proforma')
 return menu_shell('<a class="proposal-brand" href="/propuesta/">ALPHA BUILDERS<small>'+t('PROPUESTA DIGITAL','DIGITAL PROPOSAL')+'</small></a>',links,'stakeholder')
def menu_shell(brand,links,kind='buyer'):
 return f'''<header class="navigation {kind}-navigation">{brand}<button class="menu-toggle js-only" aria-expanded="false" aria-controls="primary-menu">{t('Menú','Menu')} <span aria-hidden="true">☰</span></button><nav id="primary-menu" class="primary-menu" aria-label="Principal / Main">{links}{language()}</nav></header>'''
def nav(project=False):
 brand=('<div class="project-brand">'+a('← Proyectos','← All projects','/#projects')+'<a href="/pixel/" aria-label="Pixel"><span class="pixel-word">p<span>i</span>xel<i>.</i></span></a></div>') if project else '<a class="brand" href="/" aria-label="Alpha Builders · Inicio / Home"><img class="brand-logo" src="/assets/alpha-logo-white.webp" alt="Alpha Builders" width="200" height="60"></a>'
 links=(a('El proyecto','Overview','#details')+a('Departamentos','Apartments','#homes')+a('Ubicación','Location','#location')) if project else (a('Proyectos','Projects','#projects')+a('Sobre Alpha','About Alpha','#vision'))
 links+=a('Hablar con un asesor','Talk to an advisor','#contact','advisor-link')
 return menu_shell(brand,links)+a('Hablar con un asesor','Talk to an advisor','#contact','mobile-advisor')
def map_peek():return f'''<button class="map-peek js-only" data-open="map" aria-label="Ver ubicación de Pixel"><img src="/assets/pixel-map.webp" alt="Mapa de referencia de Pixel" width="240" height="108"><span class="map-caption"><span><b>{t('Encuentra tu lugar','Find your place')}</b><br><small>PIXEL · LA MAGDALENA</small></span><span class="map-icon"><svg viewBox="0 0 20 20"><path d="M16 8c0 5-6 9-6 9S4 13 4 8a6 6 0 1 1 12 0Z"/><circle cx="10" cy="8" r="2"/></svg></span></span></button>'''
def footer(stakeholder=False):
 team=a('Equipo de la propuesta','Proposal team','/nosotros/') if stakeholder else ''
 return f'''<footer class="footer"><span>ALPHA BUILDERS © 2026</span>{team}<span>{t('Renders conceptuales generados con IA · No representan planos aprobados','AI-generated conceptual renders · Not approved architectural plans')}</span><a href="https://alphabuildershq.com/" target="_blank" rel="noopener">{t('Sitio oficial','Official website')}</a></footer>'''
def proposal():return f'''<dialog id="proposal" class="dialog"><div class="dialog-head"><b>ALPHA BUILDERS / CONCEPT STUDIO</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><div class="dialog-body">{t('Una visión compartida.<br>Tres formas de expresarla.','One shared vision.<br>Three ways to express it.','h2')}<p class="lead">{t('Una marca que inspira confianza. Cada proyecto con su propia personalidad. Información clara para quien decide rápido y una visita opcional para quien quiere descubrir más.','A brand that inspires trust. A distinct personality for every project. Clear information for quick decisions, and an optional journey for those who want to explore.')}</p><div class="proposal-grid">'''+''.join(f'''<section><small>{n} / {t(level,levelen)}</small>{t(name,nameen,'h3')}{t(desc,descen,'p')}<button class="text-link" data-choose="{s}">{t('Ver dirección','View direction')}</button></section>''' for n,level,levelen,name,nameen,desc,descen,s in [
 ('01','BÁSICO','BASIC','Esencial','Essential','Un catálogo claro para encontrar un proyecto, comparar sus datos y contactar al equipo.','A clear catalogue to find a project, compare its facts and contact the team.','essential'),
 ('02','MEDIO','MID','Editorial','Editorial','Una lectura arquitectónica del proyecto: imágenes, contexto y selección de unidades en 2D.','An architectural reading of the project: images, context and 2D home selection.','editorial'),
 ('03','ALTO','HIGH','Inmersivo','Immersive','Dirección de arte, profundidad y movimiento. Incluye la experiencia 2D, la maqueta 3D y las visitas virtuales descritas en la proforma.','Art direction, depth and motion. Includes the 2D experience, 3D model and virtual visits described in the quote.','immersive')])+f'''</div><div class="proposal-note">{t('La misma base en los tres niveles: sitio de marca, 15 sitios de proyecto y un gestor central. Medio añade selección en 2D y Alto incorpora también 3D y visitas virtuales; todos cubren el alcance obligatorio del brief.','The same foundation across all three levels: a brand site, 15 project sites and one central content system. Mid adds 2D selection and High also includes 3D and virtual visits; every tier covers the required brief scope.')}<br><br>{t('Esta muestra incluye la portada de marca, Pixel, el equipo y la proforma con demos de gestor, 2D y 3D. El inventario y las geometrías son ilustrativos; las visitas usan renders de Pixel. Los entregables de producción se rigen por la proforma y requieren planos y activos aprobados.','This preview includes the brand homepage, Pixel, the team and the quote with manager, 2D and 3D demos. Inventory and geometry are illustrative; visits use Pixel renders. Production deliverables follow the quote and require approved plans and assets.')}<br><br>{t('La opción en inglés corresponde a esta presentación. El brief establece español de Ecuador para producción. Precios, disponibilidad, estado y fechas de entrega requieren la fuente oficial aprobada.','English is available for this presentation. The brief specifies Ecuadorian Spanish for production. Prices, availability, status and delivery dates require the approved official source.')}</div><p class="source-list">{t('Imágenes y referencias:','Images and references:')} <a href="https://alphabuildershq.com/magnus/" target="_blank" rel="noopener">Alpha Builders</a> · <a href="https://pixel.com.ec/" target="_blank" rel="noopener">Pixel</a>. {t('Material de referencia para revisión privada; derechos de sus titulares.','Reference material for private review; rights remain with their owners.')}</p></div></dialog>'''
def map_dialog():return f'''<dialog id="map" class="dialog map-dialog"><div class="dialog-head"><b>{t('EL LUGAR IMPORTA','LOCATION MATTERS')}</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><img class="map-large" src="/assets/pixel-map.webp" alt="Mapa de referencia: Pixel, Av. 5 de Junio y Rodrigo de Chávez"><div class="map-details"><span class="eyebrow">QUITO / LA MAGDALENA</span><h2>Pixel</h2><p>Av. 5 de Junio y Rodrigo de Chávez, esquina.</p>{a('Abrir en Google Maps','Open in Google Maps','https://maps.app.goo.gl/JJozcsbpJE2bbfue7','button','target="_blank" rel="noopener"')}<p class="map-disclosure">{t('Mapa de referencia publicado por Pixel. La dirección también está disponible en texto; no se necesita activar tu ubicación.','Reference map published by Pixel. The address is also available as text; location access is not needed.')}</p></div></dialog>'''
def home():
 from directions import home as render_home
 render_home()

def tour_dialog():
 return f'''<dialog id="tour" class="dialog tour-dialog"><div class="dialog-head"><b>PIXEL / {t('UNA VISITA A TU RITMO','A VISIT AT YOUR PACE')}</b><button class="close" data-close aria-label="Close / Cerrar">×</button></div><div class="tour-layout"><div class="tour-stage open" id="tour-stage"><img id="tour-image" src="/assets/pixel-exterior-render.png" alt="Exterior de Pixel"><div class="door left"></div><div class="door right"></div><div class="travel-label" aria-hidden="true">PIXEL<br><small>{t('UN PASO MÁS CERCA DE CASA','ONE STEP CLOSER TO HOME')}</small></div><div class="tour-caption" aria-live="polite"><small id="scene-kicker">01 / LLEGAR</small><h2 id="scene-title">Tu primera mirada.</h2><p id="scene-description">Pixel, en La Magdalena.</p></div></div><aside class="tour-controls"><div class="eyebrow">{t('ELIGE POR DÓNDE SEGUIR','CHOOSE YOUR NEXT STEP')}</div><div class="journey-progress"><span id="journey-counter">01</span><small>/ 04</small></div><div class="floor-buttons">'''+''.join(f'<button data-scene="{i}" aria-pressed="{str(i==0).lower()}"><b>0{i+1}</b>{t(es,en)}</button>' for i,es,en in [(0,'Llegar','Arrive'),(1,'Entrar','Step inside'),(2,'Habitar','Come home'),(3,'Disfrutar','Unwind')])+f'''</div><div class="journey-actions"><button id="journey-prev" class="text-link">{t('Anterior','Previous')}</button><button id="journey-next" class="button">{t('Continuar','Continue')}</button></div><p class="tour-note">{t('Secuencia conceptual con renders 2D. Las paradas no representan pisos ni una ruta física verificada. Puedes saltar a cualquier espacio.','Conceptual sequence using 2D renders. Stops do not represent floors or a verified physical route. Jump to any space at any time.')}</p><button class="text-link" id="tour-to-details">{t('Ir directo a la información','Go straight to project details')}</button></aside></div><div class="tour-bottom"><span>{t('¿Prefieres recorrer un espacio real en 360?','Prefer to explore an existing 360 space?')}</span><a href="https://pixel.com.ec/tour360/deparNuevo/" target="_blank" rel="noopener">{t('Abrir tour 360 publicado por Pixel','Open Pixel’s existing 360 tour')}</a></div></dialog>'''
def project():
 from directions import project as render_project
 render_project()

def about():
 profiles=[
  {'name':'Martín Vélez Falconí','photo':'martin-velez-falconi.jpg','url':'https://www.linkedin.com/in/martin-velez-falconi/',
   'role':('Backend · Automatización · DevOps','Backend · Automation · DevOps'),
   'bio':('Desarrolla la base técnica que conecta aplicaciones, procesos y datos. Trabaja con Django y Odoo para construir soluciones web, y con CI/CD, Kubernetes y Azure DevOps para automatizar su despliegue y operación.','Builds the technical foundation that connects applications, workflows and data. He works with Django and Odoo to develop web solutions, and with CI/CD, Kubernetes and Azure DevOps to automate deployment and operations.'),
   'specialty':('Desarrollo backend, integración de procesos y automatización.','Backend development, workflow integration and automation.'),
   'contribution':('Conectar el gestor de contenidos con la publicación de los proyectos y facilitar su operación.','Connect the content manager to project publishing and make day-to-day operations easier.'),
   'skills':['Django','Odoo','CI/CD','Kubernetes','Azure DevOps']},
  {'name':'Alvaro Paz','photo':'alvaro-paz.jpg','url':'https://www.linkedin.com/in/alvaropaz/',
   'role':('Ingeniería de software · Frontend y backend','Software engineering · Frontend and backend'),
   'bio':('Desarrolla aplicaciones web con React y Node.js, desde la interfaz hasta la lógica del servidor. Conecta servicios e integra herramientas para crear experiencias fluidas, simplificar procesos y convertir necesidades de negocio en software útil.','Builds web applications with React and Node.js, from the interface to server-side logic. He connects services and integrates tools to create seamless experiences, simplify workflows and turn business needs into useful software.'),
   'specialty':('Desarrollo frontend, backend e integración de sistemas.','Frontend development, backend development and systems integration.'),
   'contribution':('Unir la exploración de proyectos, la selección de unidades y el contacto comercial en una experiencia coherente.','Bring project discovery, home selection and sales enquiries together in one cohesive experience.'),
   'skills':['React','Node.js','Backend','Frontend',('Integraciones','Integrations')]}
 ]
 out=head('about')+f'''<header class="team-nav"><span class="team-wordmark">ANDEAN <small>SOFTWARE LAB</small></span>{a('Volver a la propuesta','Back to proposal','/propuesta/','text-link')}</header><main id="main" class="team-main"><section class="team-intro"><div class="eyebrow">{t('SOBRE NOSOTROS / NUESTRO EQUIPO','ABOUT US / OUR TEAM')}</div>{t('De la visión<br>al <em>producto.</em>','From vision<br>to <em>product.</em>','h1')}<p>{t('Somos Andean Software Lab, el equipo de Martín Vélez Falconí y Alvaro Paz. Combinamos ingeniería de software y criterio de producto para convertir necesidades de negocio en herramientas digitales claras, útiles y fáciles de gestionar.','We are Andean Software Lab, the team of Martín Vélez Falconí and Alvaro Paz. We combine software engineering and product thinking to turn business needs into digital tools that are clear, useful and easy to manage.')}</p></section><section class="team-grid" aria-label="Perfiles / Profiles">'''
 for i,p in enumerate(profiles):
  skills=''.join('<li>'+ (t(*skill) if isinstance(skill,tuple) else skill)+'</li>' for skill in p['skills'])
  out+=f'''<article class="person-card"><div class="person-top"><span class="person-initials" aria-hidden="true">{'MV' if i==0 else 'AP'}</span><span class="person-number" aria-hidden="true">0{i+1}</span></div><p class="person-role">{t(*p['role'])}</p><h2>{p['name']}</h2><p class="person-bio">{t(*p['bio'])}</p><ul class="person-skills" aria-label="Especialidades / Specialties">{skills}</ul><dl class="person-facts"><div><dt>{t('ESPECIALIDAD','SPECIALTY')}</dt><dd>{t(*p['specialty'])}</dd></div><div><dt>{t('APORTE A LA PROPUESTA','CONTRIBUTION TO THE PROPOSAL')}</dt><dd>{t(*p['contribution'])}</dd></div></dl><a class="person-link" href="{p['url']}" target="_blank" rel="noopener noreferrer"><span class="linkedin-mark" aria-hidden="true">in</span>{t('Ver perfil en LinkedIn','View LinkedIn profile')}</a></article>'''
 out+=f'''</section><section class="team-closing"><div><span class="eyebrow">{t('NUESTRA PROPUESTA PARA ALPHA BUILDERS','OUR PROPOSAL FOR ALPHA BUILDERS')}</span>{t('De descubrir un proyecto<br>a dar el siguiente paso.','From discovering a project<br>to taking the next step.','h2')}</div><div><p>{t('Un catálogo para encontrar rápido, una lectura editorial para entender el proyecto y una experiencia inmersiva para explorarlo. Tres formas de presentar la misma información, conectadas a una gestión central.','A catalogue to find a project quickly, an editorial approach to understand it, and an immersive experience to explore it. Three ways to present the same information, connected to one central content system.')}</p>{a('Explorar el concepto','Explore the concept','/','button')}</div></section><p class="team-sources">{t('Conoce más sobre cada integrante en su perfil de LinkedIn.','Learn more about each team member on LinkedIn.')}</p></main>'''+footer(True)+'</body></html>'
 (ROOT/'nosotros').mkdir(exist_ok=True);(ROOT/'nosotros'/'index.html').write_text(out)

if __name__=='__main__':
 from proforma import proforma
 from proposal_page import proposal_page
 home();project();about();proforma();proposal_page()
